+import { Hono } from 'hono';
+import type { Env } from '../../types';
+
+interface CandidateRow {
+  id: string;
+  name: string;
+  email: string;
+  stage_id: string;
+}
+
+interface ScoreRow {
+  assessment_id: string;
+  score: number;
+}
+
+export const pipelineCandidatesRoutes = new Hono<{ Bindings: Env }>();
+
+pipelineCandidatesRoutes.get('/:id/candidates', async (c) => {
+  const pipelineId = c.req.param('id');
+
+  const candidates = await c.env.DB
+    .prepare('SELECT id, name, email, stage_id FROM candidates WHERE pipeline_id = ?1')
+    .bind(pipelineId)
+    .all<CandidateRow>();
+
+  const enriched = [];
+  for (const cand of candidates.results) {
+    const scores = await c.env.DB
+      .prepare(
+        `SELECT a.id as assessment_id, s.score
+         FROM assessments a
+         JOIN review_scores s ON s.assessment_id = a.id
+         WHERE a.candidate_id = ?1`,
+      )
+      .bind(cand.id)
+      .all<ScoreRow>();
+
+    const avgScore =
+      scores.results.length > 0
+        ? scores.results.reduce((sum, s) => sum + s.score, 0) / scores.results.length
+        : null;
+
+    enriched.push({
+      id: cand.id,
+      name: cand.name,
+      email: cand.email,
+      stageId: cand.stage_id,
+      avgScore,
+    });
+  }
+
+  // Mark all candidates as 'viewed' for analytics
+  await c.env.DB
+    .prepare('UPDATE candidates SET last_viewed_at = ?1 WHERE pipeline_id = ?2')
+    .bind(new Date().toISOString(), pipelineId)
+    .run();
+
+  return c.json({ candidates: enriched });
+});

